import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

def check_s3_bucket(bucket_name: str) -> dict:
    """Check if an S3 bucket exists and is accessible."""
    url = f"https://{bucket_name}.s3.amazonaws.com"
    try:
        resp = requests.get(url, timeout=5)
        if resp.status_code == 200:
            # Bucket exists and is publicly listable
            return {"name": bucket_name, "status": "public", "code": 200}
        elif resp.status_code == 403:
            # Bucket exists but access denied
            return {"name": bucket_name, "status": "exists", "code": 403}
        elif resp.status_code == 404:
            # Bucket doesn't exist
            return {"name": bucket_name, "status": "not_found", "code": 404}
    except requests.RequestException:
        return {"name": bucket_name, "status": "error", "code": None}

def generate_permutations(target: str) -> list:
    """Generate likely bucket names for a target."""
    prefixes = [target, f"{target}-prod", f"{target}-dev", f"{target}-staging"]
    suffixes = ["backup", "logs", "data", "media", "assets", "uploads", 
                "static", "config", "secrets", "db"]

    names = []
    for prefix in prefixes:
        for suffix in suffixes:
            names.append(f"{prefix}-{suffix}")
    return names

def scan_buckets(target: str, threads: int = 10) -> list:
    """Scan for publicly accessible S3 buckets."""
    bucket_names = generate_permutations(target)
    results = []

    with ThreadPoolExecutor(max_workers=threads) as executor:
        futures = {executor.submit(check_s3_bucket, name): name 
                   for name in bucket_names}
        for future in as_completed(futures):
            result = future.result()
            if result["status"] != "not_found":
                results.append(result)

    return sorted(results, key=lambda x: (x["status"] != "public", x["name"]))

# Run a scan (use only on authorized targets!)
results = scan_buckets("example")
for r in results:
    print(f"{r['name']}: {r['status']} ({r['code']})")
